import os,functools,http.server,threading,json,time,base64
from pathlib import Path
from datetime import datetime,timezone,timedelta
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
server=http.server.ThreadingHTTPServer(('127.0.0.1',8086),functools.partial(http.server.SimpleHTTPRequestHandler,directory=str(ROOT)))
threading.Thread(target=server.serve_forever,daemon=True).start()
now=int(time.time());future=now//3600*3600+3*3600;past=now//3600*3600-24*3600
iso=lambda t:datetime.fromtimestamp(t,timezone.utc).isoformat().replace('+00:00','Z')
points=[[39.93805,3.93665],[39.93168,3.91459]]
seed=[{'id':'plan-one','revision':1,'kind':'plan','title':'Nombre repetido','data':{'date':iso(future)[:10],'plannedStart':iso(future),'points':points,'source':'coastal','estimatedMinutes':120,'estimateMode':'manual','roundtrip':True,'paceMinutesPerKm':20,'notes':'Notas originales del plan','photos':[],'markers':[]}}, {'id':'trip-one','revision':1,'kind':'trip','title':'Nombre repetido','data':{'date':iso(past)[:10],'points':points,'source':'gpx','duration':80,'wind':'Viento antiguo sin reinterpretar','sea':'Notas antiguas del mar','photos':[],'markers':[],'forecastBaseline':{'version':1,'point':points[0],'targetTime':past,'validTime':past,'capturedAt':(past-86400)*1000,'windSpeed':12,'windGust':36,'waveHeight':.5,'source':'Open-Meteo'}}}, {'id':'access-one','revision':1,'kind':'place','title':'Acceso guardado','data':{'category':'access','point':points[0],'notes':'Conservar notas del acceso','customFlag':'preservar'}}, {'id':'prefs','revision':1,'kind':'preferences','title':'Preferencias','data':{'hideGuide':True,'paceMinutesPerKm':20,'weatherLimits':{'wind':2,'gust':4,'wave':.4},'weatherFavorites':[{'id':'fav-one','title':'Cala favorita','point':points[0]}],'sunMode':False}}]
backend="""let current={id:'test',email:'test@example.invalid'},listener;const stores=JSON.parse(sessionStorage.getItem('sea-test-stores')||'null')||{test:SEED,other:[]};window.testRows=(id='test')=>structuredClone(stores[id]||[]);window.testSwitch=id=>{current=id?{id,email:id+'@example.invalid'}:null;listener('SIGNED_IN',current?{user:current}:null);};export async function getClient(){return {auth:{getSession:async()=>({data:{session:{user:current}}}),onAuthStateChange:f=>listener=f}};}export async function loadEntries(){return structuredClone(stores[current?.id]||[]);}export async function saveEntry(e,owner='test'){const rows=stores[owner]||[];let old=rows.find(x=>x.id===e.id);if(old&&old.revision!==e.revision)throw Error('Conflicto de versión');const row={...structuredClone(e),revision:(e.revision||0)+1};if(old)rows[rows.indexOf(old)]=row;else rows.push(row);stores[owner]=rows;sessionStorage.setItem('sea-test-stores',JSON.stringify(stores));return row;}export async function signedPhoto(){return './guide-photo.svg';}export async function uploadPhoto(file,id){return {id:'visit-photo',path:id+'/visit.png',name:file.name};}""".replace('SEED',json.dumps(seed))
scenario={'wind':12,'gust':36,'wave':.5,'weather_fail':False,'search_fail':False}
def weather(url):
 from urllib.parse import urlparse,parse_qs
 q=parse_qs(urlparse(url).query);lats=q.get('latitude',['40'])[0].split(',');lons=q.get('longitude',['4'])[0].split(',');t=int(time.time())//3600*3600;times=[t+i*3600 for i in range(168)]
 rows=[{'latitude':float(a),'longitude':float(b),'hourly':{'time':times,'temperature_2m':[20]*168,'wind_speed_10m':[scenario['wind']]*168,'wind_gusts_10m':[scenario['gust']]*168,'wind_direction_10m':[45]*168,'wave_height':[scenario['wave']]*168,'wave_direction':[90]*168,'wave_period':[5]*168}} for a,b in zip(lats,lons)]
 return rows if len(rows)>1 else rows[0]
def setup(browser,width):
 scenario.update(wind=12,gust=36,wave=.5,weather_fail=False,search_fail=False)
 context=browser.new_context(viewport={'width':width,'height':900},service_workers='block',reduced_motion='reduce');page=context.new_page();errors=[]
 page.on('pageerror',lambda e:(errors.append(str(e)),print('SEA_PAGE_ERROR',str(e),flush=True)));page.on('dialog',lambda d:d.accept())
 page.add_init_script("Object.defineProperty(navigator,'canShare',{value:()=>false,configurable:true});")
 page.route('**/backend.js*',lambda r:r.fulfill(body=backend,content_type='text/javascript'))
 page.route('**/api.open-meteo.com/**',lambda r:r.fulfill(status=503,body='unavailable') if scenario['weather_fail'] else r.fulfill(json=weather(r.request.url)))
 page.route('**/marine-api.open-meteo.com/**',lambda r:r.fulfill(json=weather(r.request.url)))
 page.route('**/photon.komoot.io/**',lambda r:r.fulfill(status=503,body='unavailable') if scenario['search_fail'] else r.fulfill(json={'features':[{'geometry':{'coordinates':[4.02,40.08]},'properties':{'osm_type':'N','osm_id':123,'name':'Cala de prueba'}},{'geometry':{'coordinates':[0,51]},'properties':{'osm_type':'N','osm_id':124,'name':'Fuera de Menorca'}}]}))
 page.route('**/embed.windy.com/**',lambda r:r.fulfill(body='<html>Windy simulado</html>',content_type='text/html'))
 hook="\nwindow.seaTest={wind:()=>windUI,map:()=>map,openForecast,view:viewAdventure,state:()=>({draft:structuredClone(draft),mode,practice:!!practice,entries:structuredClone(entries),account:user?.id}),format:madridInput};"
 page.route('**/app.js*',lambda r:r.fulfill(body=(ROOT/'app.js').read_text()+hook,content_type='text/javascript'))
 page.goto('http://127.0.0.1:8086/',wait_until='networkidle');page.wait_for_function("window.seaTest&&seaTest.state().entries.length===4&&!document.querySelector('#meteo-map-hours').disabled")
 return context,page,errors
def close(page):
 if page.locator('#content-dialog').is_visible():page.locator('#content-dialog [data-close]').click()
def adventure(page,id):
 close(page);page.evaluate('(id)=>seaTest.view(id)',id);page.wait_for_selector('#adventure-sheet')
def check(page,errors,width):
 assert not errors,errors;assert page.evaluate('document.documentElement.scrollWidth')<=width+1

def map_tools(page,errors,width):
 original=page.evaluate('testRows()');page.locator('#sea-reference').click();page.locator('[data-sea=choose-reference]').click();page.locator('#map').click(position={'x':110,'y':110});assert page.evaluate('seaTest.wind().getReference().pinned');fixed=page.evaluate('seaTest.wind().getReference().point');page.evaluate('seaTest.map().panTo([40.1,4.3],{animate:false})');assert page.evaluate('seaTest.wind().getReference().point')==fixed
 page.locator('#sea-reference').click();page.locator('[data-sea=follow-center]').click();assert not page.evaluate('seaTest.wind().getReference().pinned')
 page.locator('#sea-freshness').click();assert 'consulta' in page.locator('#content-body').inner_text().lower();assert 'Open-Meteo' in page.locator('#content-body').inner_text();close(page)
 adventure(page,'plan-one');assert page.locator('#sea-window').is_visible();assert 'Regreso' in page.locator('#sea-return').inner_text();page.locator('#sea-depart').click();actual=page.evaluate('seaTest.wind().getGeneralTime()');assert abs(actual-future)<=1800;page.locator('#sea-return').click();assert abs(page.evaluate('seaTest.wind().getGeneralTime()')-(future+7200))<=1800;assert page.locator('.ruler-plan-anchor').count()==2
 page.locator('#sea-sun').click();page.wait_for_function("document.body.classList.contains('sun-mode')");assert page.evaluate("testRows().find(e=>e.kind==='preferences').data.hideGuide") is True;assert page.evaluate("testRows().find(e=>e.kind==='preferences').data.paceMinutesPerKm")==20
 page.set_viewport_size({'width':width,'height':600});page.wait_for_timeout(200);key=page.locator('.map-color-legend').bounding_box();actions=page.locator('.map-actions').bounding_box();assert actions['y']+actions['height']<=key['y'],(actions,key);page.set_viewport_size({'width':width,'height':900});page.locator('#sea-sun').click();page.wait_for_function("!document.body.classList.contains('sun-mode')")
 assert all(next(r for r in page.evaluate('testRows()') if r['id']==e['id'])==e for e in original if e['kind']!='preferences');check(page,errors,width)

def personal_tools(page,errors,width):
 page.locator('[data-sea=favorites]').click();page.locator('#sea-favorites-form button').click();page.wait_for_function("document.querySelector('#sea-favorites-results').textContent.includes('Fuerza')");assert page.locator('#sea-favorites-results [data-kind=wind]').get_attribute('data-force')=='2';assert page.locator('#sea-favorites-results [data-kind=gust]').get_attribute('data-force')=='5';assert 'Supera tus límites' in page.locator('#sea-favorites-results').inner_text()
 page.locator('[data-sea=limits]').click();form=page.locator('#sea-limits-form');form.locator('[name=wind]').fill('3');form.locator('[name=gust]').fill('3');form.locator('[name=wave]').fill('');form.locator('button').click();page.wait_for_function("document.querySelector('#sea-limits-state').textContent.includes('guardados')");prefs=page.evaluate("testRows().find(e=>e.kind==='preferences').data");assert prefs['weatherLimits']=={'wind':3,'gust':3};assert prefs['hideGuide'] is True and prefs['paceMinutesPerKm']==20;close(page)
 page.locator('[data-sea=search]').click();form=page.locator('#sea-search-form');form.locator('[name=query]').fill('Cala');form.locator('button').click();page.wait_for_selector('[data-search-use]');assert 'Cala de prueba' in page.locator('#sea-search-results').inner_text();assert 'Fuera de Menorca' not in page.locator('#sea-search-results').inner_text();page.locator('[data-use=favorite]').first.click();page.wait_for_function("document.querySelector('#sea-search-state').textContent.includes('añadida')");assert len(page.evaluate("testRows().find(e=>e.kind==='preferences').data.weatherFavorites"))==2;close(page)
 page.reload(wait_until='networkidle');page.wait_for_function('window.seaTest&&seaTest.state().entries.length===4');assert page.evaluate("testRows().find(e=>e.kind==='preferences').data.weatherLimits")=={'wind':3,'gust':3};assert len(page.evaluate("testRows().find(e=>e.kind==='preferences').data.weatherFavorites"))==2

 check(page,errors,width)

def route_tools(page,errors,width):
 adventure(page,'plan-one');page.locator('#adventure-sheet [data-sea=route-weather]').click();page.wait_for_function("!document.querySelector('#sea-reference-save').disabled");page.locator('#sea-reference-save').click();page.wait_for_function("document.querySelector('#sea-route-state').textContent.includes('Referencia guardada')");row=page.evaluate("testRows().find(e=>e.id==='plan-one')");assert row['data']['notes']=='Notas originales del plan';assert row['data']['forecastBaseline']['targetTime']==future;assert row['data']['forecastBaseline']['durationMinutes']==120
 close(page);scenario.update(wind=27,gust=45,wave=.8);adventure(page,'plan-one');page.locator('#adventure-sheet [data-sea=route-weather]').click();page.wait_for_function("document.querySelector('#sea-route-current').textContent.includes('Cambios desde')");assert 'Fuerza 2' in page.locator('#sea-route-current').inner_text() and 'Fuerza 4' in page.locator('#sea-route-current').inner_text();close(page)
 adventure(page,'plan-one');page.locator('#adventure-sheet [data-action=edit]').click();page.locator('#entry-form [name=notes]').fill('Borrador protegido');page.locator('#close-editor').click();before=page.evaluate('seaTest.state().draft');page.locator('[data-sea=search]').click();page.locator('#sea-search-form [name=query]').fill('Acceso');page.locator('[data-use=plan]').click();assert page.locator('#editor-dialog').is_visible();assert page.evaluate('seaTest.state().draft.id')==before['id'];assert page.locator('#entry-form [name=notes]').input_value()=='Borrador protegido';page.locator('#close-editor').click()
 page.locator('#weather-button').click();page.locator('#map').click(position={'x':120,'y':100});page.wait_for_selector('#meteo-dialog[open]');page.locator('#wind-full').click();page.wait_for_selector('svg[data-weather-chart]');points=page.locator('.chart-pick');assert points.count()>2;target=points.nth(1).get_attribute('data-forecast-hour');points.nth(1).focus();points.nth(1).press('Enter');page.wait_for_function('(t)=>document.querySelector("#weather-result").dataset.time===t',arg=target);assert page.evaluate('seaTest.state().draft.id')==before['id'];close(page);check(page,errors,width)

