 page.locator('#menu-button').click();page.locator('[data-menu=places]').click();page.locator('[data-action=place-detail][data-id=access-one]').click();page.locator('[data-sea=visit]').click();form=page.locator('#sea-visit-form');form.locator('[name=notes]').fill('Escalones revisados');form.locator('[name=status]').select_option('difficult');form.locator('[name=photo]').set_input_files({'name':'visita.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jK1sAAAAASUVORK5CYII=')});form.locator('button').click();page.wait_for_function("document.querySelector('#sea-visit-state').textContent.includes('guardada')");row=page.evaluate("testRows().find(e=>e.id==='access-one')");assert row['data']['customFlag']=='preservar' and row['data']['notes']=='Conservar notas del acceso';assert row['data']['visit']['photo']['path']=='test/visit.png';close(page)
 page.locator('#menu-button').click();page.locator('[data-menu=places]').click();page.locator('[data-action=place-detail][data-id=access-one]').click();assert 'Escalones revisados' in page.locator('#content-body').inner_text();page.locator('[data-action=edit-place]').click();page.locator('#place-form [name=title]').fill('Acceso renombrado');page.locator('#place-form button').click();page.wait_for_selector('[data-action=place-detail][data-id=access-one]');assert page.evaluate("testRows().find(e=>e.id==='access-one').data.visit.notes")=='Escalones revisados';page.locator('[data-sea=place-plan][data-sea-id=access-one]').click();draft=page.evaluate('seaTest.state().draft');assert draft['kind']=='plan';assert len(draft['data']['anchors'])==1;assert draft['data']['departure']=='Acceso renombrado';check(page,errors,width)

