 adventure(page,'trip-one');page.locator('#adventure-sheet [data-sea=observe]').click();form=page.locator('#sea-observation-form');form.locator('[name=at]').fill(page.evaluate('(t)=>seaTest.format(t)',past));form.locator('[name=wind]').fill('3');form.locator('[name=gust]').fill('6');form.locator('[name=wave]').fill('0.7');form.locator('[name=notes]').fill('Más rachas de las esperadas');form.locator('button').click();page.wait_for_function("document.querySelector('#sea-observation-state').textContent.includes('guardada')");trip=page.evaluate("testRows().find(e=>e.id==='trip-one')");assert trip['data']['wind']=='Viento antiguo sin reinterpretar';assert trip['data']['observations']['wind']==3;close(page);adventure(page,'trip-one');assert page.locator('.observation-summary table').is_visible();assert 'Más rachas' in page.locator('.observation-summary').inner_text()
 page.locator('#adventure-sheet [data-sea=share]').click();page.wait_for_function("!document.querySelector('#sea-share-download').disabled");assert page.locator('#sea-share-canvas').evaluate('c=>[c.width,c.height]')==[960,1080];initial=page.locator('#sea-share-canvas').evaluate('c=>c.toDataURL()');page.locator('#sea-share-fields [name=date]').uncheck();page.wait_for_function("!document.querySelector('#sea-share-download').disabled");assert page.locator('#sea-share-canvas').evaluate('c=>c.toDataURL()')!=initial
 with page.expect_download() as download:page.locator('#sea-share-download').click()
